package org.humanjourney.core.geography.map;
import java.util.*;
import java.nio.file.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.humanjourney.core.geography.map.client.*;
class BoundaryControlTest {
 final BoundaryControlLayout.Rect button=new BoundaryControlLayout.Rect(100,10,118,20);
 @Test void controlStartsTopRightAndAvoidsNativeWidgetBounds(){var first=BoundaryControlLayout.place(1000,600,List.of()).orElseThrow();assertEquals(874,first.x());assertEquals(8,first.y());var next=BoundaryControlLayout.place(1000,600,List.of(first)).orElseThrow();assertFalse(next.overlaps(first));}
 @Test void tinyOrFullyOccupiedScreenHasNoOverlappingFallback(){assertTrue(BoundaryControlLayout.place(100,30,List.of()).isEmpty());assertTrue(BoundaryControlLayout.place(1000,600,List.of(new BoundaryControlLayout.Rect(0,0,1000,600))).isEmpty());}
 @Test void leftClickInsideCyclesAndOwnsReleaseAndDrag(){var input=new BoundaryControlInput();assertEquals(BoundaryControlInput.Action.CYCLE,input.press(button,true,110,15,0));assertTrue(input.drag(0));assertTrue(input.release(0));assertFalse(input.drag(0));assertFalse(input.release(0));}
 @Test void rightClickInsideCannotCreateWaypointBehindControl(){var input=new BoundaryControlInput();assertEquals(BoundaryControlInput.Action.CONSUME,input.press(button,true,110,15,1));assertTrue(input.release(1));}
 @Test void clicksOutsideAndDisabledControlNeverCaptureMapGestures(){for(double x:new double[]{0,99,218,1000}){var input=new BoundaryControlInput();assertEquals(BoundaryControlInput.Action.PASS,input.press(button,true,x,15,0));assertFalse(input.drag(0));assertFalse(input.release(0));}var input=new BoundaryControlInput();assertEquals(BoundaryControlInput.Action.PASS,input.press(button,false,110,15,0));assertFalse(input.release(0));}
 @Test void hitBoundsMatchNativeExclusiveRightAndBottom(){var input=new BoundaryControlInput();assertEquals(BoundaryControlInput.Action.CYCLE,input.press(button,true,100,10,0));assertEquals(BoundaryControlInput.Action.PASS,input.press(button,true,218,10,0));assertEquals(BoundaryControlInput.Action.PASS,input.press(button,true,100,30,0));}
 @Test void unrelatedMouseButtonReleaseDoesNotLoseCapturedGesture(){var input=new BoundaryControlInput();input.press(button,true,110,15,0);assertFalse(input.release(1));assertTrue(input.drag(0));assertTrue(input.release(0));}
 @Test void controlIsGatedAndUsesOnlyPublicForgeScreenEvents()throws Exception{var root=Path.of(System.getProperty("humanjourney.projectDir"));String client=Files.readString(root.resolve("src/main/java/org/humanjourney/core/integration/xaero/client/XaeroClient.java"));assertTrue(client.contains("if(!XaeroStatus.state().supported())return"));assertTrue(client.contains("XaeroBoundaryControl"));String ui=Files.readString(root.resolve("src/main/java/org/humanjourney/core/integration/xaero/client/XaeroBoundaryControl.java"));assertTrue(ui.contains("ScreenEvent.Init.Post.BUS"));assertTrue(ui.contains("instanceof GuiMap"));assertTrue(ui.contains("event.addListener(entry.button)"));assertTrue(ui.contains("ScreenEvent.MouseButtonPressed.Pre.BUS"));assertTrue(ui.contains("GeographyClientConfig.mode().next()"));assertFalse(ui.contains("MapNetwork"));assertFalse(ui.contains("MapServer"));assertTrue(ui.contains("config-based boundaries remain usable"));}
 @Test void tooltipMethodAndOffsetRemainIdenticalToApprovedBaseline()throws Exception{var root=Path.of(System.getProperty("humanjourney.projectDir"));String source=Files.readString(root.resolve("src/main/java/org/humanjourney/core/integration/xaero/client/Xaero13913Adapter.java"));String tooltip=source.substring(source.indexOf(" private static String fit("),source.indexOf(" private Xaero13913Adapter()"));assertEquals("519b29547734f83a596388a447899a7f54d51ad9f9baee8377615149f85d7493",java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(tooltip.getBytes(java.nio.charset.StandardCharsets.UTF_8))));assertEquals(1,source.split("map.index().hover",-1).length-1);assertTrue(source.contains("BoundaryPresentation.plan(map.index(),dim,view,mode,hover)"));assertTrue(source.contains("tooltip(g,hover,mouseX,mouseY,screen.width,screen.height)"));}
}
